begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.pa(t text) returns uuid language sql immutable as $$select md5('programming-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.pa(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.pa(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-programming@example.invalid',now(),now(),now() from unnest(array['owner','member'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.pa('org'),'Programação fictícia','programming-test','active'),(pg_temp.pa('other'),'Outro ministério fictício','programming-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.pa('unit'),pg_temp.pa('org'),'Igreja fictícia A','a','headquarters'),(pg_temp.pa('unitb'),pg_temp.pa('org'),'Igreja fictícia B','b','campus'),(pg_temp.pa('outside'),pg_temp.pa('other'),'Externa fictícia','outside','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.pa(t||'-m'),pg_temp.pa('org'),pg_temp.pa(t),pg_temp.pa('unit'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member'])t;
create function pg_temp.cmd(a text,i uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.programming_admin(pg_temp.pa('org'),pg_temp.pa('unit'),a,i,v,d)$$;
create function pg_temp.first() returns timestamp language sql stable as $$select make_timestamp(extract(year from now())::integer+1,1,31,19,0,0)$$;
create function pg_temp.fields() returns jsonb language sql as $$select jsonb_build_object('title','Culto fictício de domingo','description','Somente teste local','kind','service','startsLocal',to_char(pg_temp.first(),'YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char(pg_temp.first()+interval '2 hours','YYYY-MM-DD"T"HH24:MI'),'location','Local fictício','address','','capacity',10,'category',pg_temp.pa('cat'),'cover','','repeat','monthly','count',3)$$;
create function pg_temp.ev(n integer) returns uuid language sql security definer set search_path='' as $$select id from private.church_app_events where organization_id=pg_temp.pa('org') order by starts_at,id offset n limit 1$$;
create function pg_temp.detail(n integer) returns jsonb language sql as $$select pg_temp.cmd('detail',pg_temp.ev(n))$$;
select pg_temp.actor('owner');set local role authenticated;
select pg_temp.cmd('category',pg_temp.pa('cat'),0,'{"name":"Cultos","color":"#285c45","active":true}');
create function pg_temp.info() returns jsonb language sql as $$select '{"venue":{"format":"online","church":"","postal_code":"","street":"","number":"","complement":"","district":"","city":"","state":"","onlineUrl":"https://example.com/encontro"},"scope":"selected","targets":[],"group":"","groupVersion":0,"schedule":[],"guests":[],"contacts":{"phone":"","whatsapp":"","email":"","instagram":"","facebook":"","youtube":"","website":""},"gallery":[],"team":[]}'::jsonb||jsonb_build_object('targets',jsonb_build_array(pg_temp.pa('unit'),pg_temp.pa('unitb')))$$;
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'choices')$$,'seleções limitadas à organização');
select is(jsonb_array_length(public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'choices')->'units'),2,'não expõe igrejas de outro ministério');
select lives_ok($$select pg_temp.cmd('create',pg_temp.pa('request'),null,pg_temp.fields()||jsonb_build_object('information',pg_temp.info()))$$,'cria série e informações atomicamente');
select lives_ok($$select pg_temp.cmd('create',pg_temp.pa('request'),null,pg_temp.fields()||jsonb_build_object('information',pg_temp.info()))$$,'repetição da mesma tentativa não duplica');
select is(public.member_event_page(pg_temp.ev(0)),null::jsonb,'rascunho não aparece no link público');
select is(pg_temp.detail(0)->'information'->'venue'->>'format','online','formato ligado ao cadastro canônico');
select lives_ok($$select pg_temp.cmd('publish',pg_temp.ev(0),1,jsonb_build_object('future',false,'versions',pg_temp.detail(0)->'versions'))$$,'publica evento com link online válido');
select is(public.member_event_page(pg_temp.ev(0))->'event'->>'id',pg_temp.ev(0)::text,'página usa mesmo evento e não uma cópia');
select ok(not(public.member_event_page(pg_temp.ev(0))::text like '%team%'),'página pública não expõe equipe interna');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),1,pg_temp.info())$$,'40001','member_event_changed','versão antiga recusada');
select throws_ok($$select pg_temp.cmd('edit',pg_temp.ev(1),1,(pg_temp.fields()-'repeat'-'count')||jsonb_build_object('future',false,'versions',pg_temp.detail(1)->'versions','information',pg_temp.info()||jsonb_build_object('targets',jsonb_build_array(pg_temp.pa('outside')))))$$,'42501','member_agenda_denied','destino de outro ministério recusado');
select is(jsonb_array_length(public.member_agenda(pg_temp.pa('org'),pg_temp.pa('unitb'))->'items'),1,'igreja destinatária vê o mesmo evento publicado');
select is(public.member_agenda(pg_temp.pa('org'),pg_temp.pa('unitb'))->'items'->0->>'id',pg_temp.ev(0)::text,'divulgação não duplica evento e vagas');
select is(jsonb_array_length(public.member_agenda(pg_temp.pa('other'),pg_temp.pa('outside'))->'items'),0,'agenda de outro ministério permanece isolada');
select is(public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'preview',pg_temp.ev(1))->>'preview','true','administrador confere prévia privada do rascunho');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),2,jsonb_set(pg_temp.info(),'{venue,onlineUrl}','""'))$$,'22023','invalid_event_information','não remove link obrigatório de evento publicado');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),2,pg_temp.info()||jsonb_build_object('team',jsonb_build_array(pg_temp.pa('member'))))$$,'atribui colaborador confirmado somente ao evento');
select pg_temp.actor('member');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'read',pg_temp.ev(0))$$,'colaborador consulta evento designado');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),3,jsonb_set(pg_temp.info()||jsonb_build_object('team',jsonb_build_array(pg_temp.pa('member'))),'{contacts,email}','"contato@example.invalid"'))$$,'colaborador edita contato público sem ganhar administração');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),4,pg_temp.info())$$,'42501','member_agenda_denied','colaborador não muda equipe ou destinos');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'preview',pg_temp.ev(0))$$,'42501','member_agenda_denied','colaborador não recebe prévia administrativa');
select pg_temp.actor('owner');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),4,pg_temp.info())$$,'administrador remove designação do evento');
select pg_temp.actor('member');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'read',pg_temp.ev(0))$$,'42501','member_agenda_denied','revogação da equipe vale imediatamente');
select pg_temp.actor('owner');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(0),5,pg_temp.info()||jsonb_build_object('targets',jsonb_build_array(pg_temp.pa('unitb'))))$$,'seleciona destinatário diferente da igreja organizadora');
select is(jsonb_array_length(public.member_agenda(pg_temp.pa('org'),pg_temp.pa('unit'))->'items'),0,'agenda da organizadora respeita exclusão dos destinatários');
select is(jsonb_array_length(public.member_agenda(pg_temp.pa('org'),pg_temp.pa('unitb'))->'items'),1,'destinatária mantém divulgação do evento único');
select lives_ok($$select public.event_image_command(pg_temp.pa('org'),pg_temp.pa('unit'),pg_temp.pa('image'),'prepare','image/png')$$,'prepara imagem no escopo autorizado');
select is(public.member_event_image(pg_temp.pa('image')),null::jsonb,'imagem incompleta nunca é servida');
select lives_ok($$select public.event_image_command(pg_temp.pa('org'),pg_temp.pa('unit'),pg_temp.pa('image'),'finish')$$,'confirma imagem privada do administrador');
select throws_ok($$select public.event_image_command(pg_temp.pa('org'),pg_temp.pa('outside'),pg_temp.pa('image2'),'prepare','image/png')$$,'42501','community_denied','upload para outro ministério é recusado');
select lives_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'save',pg_temp.ev(1),1,pg_temp.info()||jsonb_build_object('schedule',jsonb_build_array(jsonb_build_object('id',pg_temp.pa('activity'),'title','Acolhimento','starts',pg_temp.detail(1)->'event'->>'starts_at','ends',(pg_temp.detail(1)->'event'->>'starts_at')::timestamptz+interval '30 minutes','location','Salão'))))$$,'programação salva dentro do encontro');
select lives_ok($$select pg_temp.cmd('edit',pg_temp.ev(1),2,(pg_temp.fields()-'repeat'-'count')||jsonb_build_object('startsLocal',to_char((pg_temp.detail(1)->'event'->>'starts_at')::timestamptz at time zone 'America/Sao_Paulo'+interval '1 day','YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char((pg_temp.detail(1)->'event'->>'ends_at')::timestamptz at time zone 'America/Sao_Paulo'+interval '1 day','YYYY-MM-DD"T"HH24:MI'),'future',true,'versions',pg_temp.detail(1)->'versions','information',pg_temp.info()))$$,'editar série preserva e desloca programação individual');
select is((pg_temp.detail(1)->'information'->'schedule'->0->>'starts')::timestamptz,(pg_temp.detail(1)->'event'->>'starts_at')::timestamptz,'atividade acompanha nova data sem sair do encontro');
select is(jsonb_array_length(pg_temp.detail(2)->'information'->'schedule'),0,'encontro seguinte preserva sua própria programação');
select pg_temp.actor('member');
select throws_ok($$select public.event_information_admin(pg_temp.pa('org'),pg_temp.pa('unit'),'choices')$$,'42501','member_agenda_denied','membro não lista equipe da administração');
select ok(not has_function_privilege('authenticated','private.programming_admin_base_20261103(uuid,uuid,text,uuid,integer,jsonb)','execute'),'base anterior não permite contornar novas regras');
select ok(not has_function_privilege('anon','public.event_information_admin(uuid,uuid,text,uuid,integer,jsonb)','execute'),'visitante não altera informações');
select finish();rollback;
